using Row=array<uint8_t,28>;
uint8_t mt[29][29];int iv[29];
struct Affine {array<Row,27> R{};uint32_t pivot=0;int rank=0;
 bool add(Row a){for(int j=0;j<27;j++)if(a[j]&&(pivot>>j&1)){auto&b=R[j];auto*t=mt[a[j]];for(int i=j+1;i<28;i++){int z=a[i]-t[b[i]];a[i]=z<0?z+29:z;}a[j]=0;}
 int j=0;while(j<27&&!a[j])j++;if(j==27)return a[27]==0;auto*t=mt[iv[a[j]]];for(int i=j+1;i<28;i++)a[i]=t[a[i]];a[j]=1;
 for(int k=0;k<27;k++)if((pivot>>k&1)&&R[k][j]){auto&b=R[k];auto*t2=mt[b[j]];for(int i=j+1;i<28;i++){int z=b[i]-t2[a[i]];b[i]=z<0?z+29:z;}b[j]=0;}
 R[j]=a;pivot|=1u<<j;rank++;return true;}
 bool relation(int c,int p,int d,int q){array<int,29>x{};x[c]++;x[p]--;x[d]--;x[q]++;Row r{};for(int i=2;i<29;i++)r[i-2]=mod(x[i]);r[27]=mod(-x[1]);return add(r);}
 bool distinct()const{array<Row,29> expr{};expr[1][27]=1;for(int i=0;i<27;i++){if(pivot>>i&1){expr[i+2]=R[i];expr[i+2][i]=0;for(int j=0;j<27;j++)if(expr[i+2][j])expr[i+2][j]=29-expr[i+2][j];}else expr[i+2][i]=1;}for(int i=0;i<29;i++)for(int j=0;j<i;j++)if(expr[i]==expr[j])return false;return true;}
 bool join(const Affine&b){for(int j=0;j<27;j++)if(b.pivot>>j&1){if(!add(b.R[j]))return false;}return distinct();}
 template<class F>bool charts(F callback,long long cap=50000)const{if(rank<23)throw runtime_error("too many free");Chart a{};array<Row,29> expr{};expr[1][27]=1;vector<int> free;for(int i=0;i<27;i++){if(pivot>>i&1){expr[i+2]=R[i];expr[i+2][i]=0;for(int j=0;j<27;j++)if(expr[i+2][j])expr[i+2][j]=29-expr[i+2][j];}else{expr[i+2][i]=1;free.push_back(i);}}
 vector<uint32_t> need(29);for(int c=0;c<29;c++)for(int f:free)if(expr[c][f])need[c]|=1u<<f;uint32_t done=0;vector<int> order;vector<vector<int>> ready(1);for(int c=0;c<29;c++)if(!need[c])ready[0].push_back(c);for(int i=0;i<(int)free.size();i++){int best=-1,bscore=-1;for(int f:free)if(!(done>>f&1)){int score=0;for(int c=0;c<29;c++)if((need[c]>>f&1)){score+=1;if((need[c]&~(done|(1u<<f)))==0)score+=100;}if(score>bscore){bscore=score;best=f;}}order.push_back(best);ready.emplace_back();uint32_t prev=done;done|=1u<<best;for(int c=0;c<29;c++)if((need[c]&~prev)&&!(need[c]&~done))ready.back().push_back(c);}
 uint32_t used=0;for(int c:ready[0]){int v=expr[c][27];if(used>>v&1)return true;used|=1u<<v;a[c]=v;}long long nodes=0;bool complete=true;function<bool(int,uint32_t)> dfs=[&](int i,uint32_t mask){if(++nodes>cap){complete=false;return false;}if(i==(int)order.size())return callback(a);int f=order[i];for(int q=2;q<29;q++)if(!(mask>>q&1)){a[f+2]=q;uint32_t m=mask;bool ok=true;for(int c:ready[i+1]){int z=expr[c][27];for(int h=0;h<=i;h++)z+=expr[c][order[h]]*a[order[h]+2];int v=mod(z);if(m>>v&1){ok=false;break;}m|=1u<<v;a[c]=v;}if(ok&&!dfs(i+1,m))return false;}return true;};dfs(0,used);return complete;}

};
struct Active{const Lex*lex;vector<pair<int,int>> cp;double w;};
vector<Active> options(const Model&m,int g,int cap){vector<Active> out;for(int i:m.byGroup[g]){auto&c=m.cand[i];auto&p=c.lex->p;vector<pair<int,int>> a;for(int j=0;j<(int)p.size();j++)if(p[j])a.push_back({m.groups[g].c[j],p[j]});if(a.size()<8)continue;out.push_back({c.lex,move(a),c.lex->weight});}stable_sort(out.begin(),out.end(),[](auto&a,auto&b){return a.w>b.w;});if(cap>0&&(int)out.size()>cap)out.resize(cap);return out;}
bool addword(Affine&st,const Active&a){for(int i=8;i<(int)a.cp.size();i++)if(!st.relation(a.cp[i].first,a.cp[i].second,a.cp[i-8].first,a.cp[i-8].second))return false;return st.distinct();}
bool addsecond(Affine&st,const Active&a,const Active&b,int phase){for(int i=0;i<(int)b.cp.size();i++){auto[c,p]=b.cp[i];auto[d,q]=a.cp[(phase+i)%8];if((c==d)!=(p==q)||(c==p)!=(d==q))return false;if(!st.relation(c,p,d,q))return false;}return st.distinct();}
struct Hyp{Affine st;double weight;int a,b,phase;};
struct PairSet{int g,h,chapter;double estimate;vector<Hyp> state;};
vector<Hyp> build(const vector<Active>&A,const vector<Active>&B){vector<Hyp> v;for(int i=0;i<(int)A.size();i++){Affine st;if(!addword(st,A[i]))continue;for(int j=0;j<(int)B.size();j++)for(int ph=0;ph<8;ph++){auto h=st;if(addsecond(h,A[i],B[j],ph))v.push_back({h,A[i].w*B[j].w,i,j,ph});}}stable_sort(v.begin(),v.end(),[](auto&a,auto&b){return a.weight>b.weight;});return v;}
struct TrieNode{array<int,29> next{};bool terminal=false;};vector<TrieNode> trie(1);void maketrie(){for(int l=1;l<30;l++)for(auto&w:D[l]){int n=0;for(int p:w.p){int q=trie[n].next[p];if(!q){q=trie.size();trie[n].next[p]=q;trie.emplace_back();}n=q;}trie[n].terminal=true;}}
bool supports(const Word&c,const Chart&a,const Chart&b,const Key&k){auto dfs=[&](auto&&self,int i,int phase,int node)->bool{if(i==(int)c.size())return trie[node].terminal;int x=c[i];if(x==0){int z=trie[node].next[0];if(z&&self(self,i+1,phase,z))return true;}int p=b[mod(a[x]-k[phase])];if(p){int z=trie[node].next[p];if(z&&self(self,i+1,(phase+1)&7,z))return true;}return false;};for(int phase=0;phase<8;phase++)if(dfs(dfs,0,phase,0))return true;return false;}
bool anchorfilter(const vector<Group>&g,const Chart&a,const PairSet&s,const Hyp&h,const vector<vector<Active>>&opt){Key k;if(!wordkey(g[s.g].c,opt[s.g][h.a].lex->p,a,k))throw runtime_error("anchor not legal");Chart b;for(int i=0;i<29;i++)b[a[i]]=i;vector<int> gg;for(int i=0;i<(int)g.size();i++)if(g[i].chapter==s.chapter&&i!=s.g&&i!=s.h)gg.push_back(i);stable_sort(gg.begin(),gg.end(),[&](int i,int j){return g[i].c.size()>g[j].c.size();});int needed=max(1,(int)ceil(0.6*(gg.size()+2))-2),yes=0;for(int i=0;i<(int)gg.size();i++){yes+=supports(g[gg[i]].c,a,b,k);if(yes>=needed)return true;if(yes+(int)gg.size()-i-1<needed)return false;}return yes>=needed;}
struct Result{Chart chart{};int support=0;vector<Key> key;vector<int> votes;};
// Only a candidate chart that yields repeat key support across multiple chapters is accepted.
Result scorechart(Model&m,const Chart&a,int threshold=4){Result out;out.chart=a;vector<map<Key,int>> votes(9);for(size_t gi=0;gi<m.groups.size();gi++){auto&g=m.groups[gi];set<Key> keys;for(int i:m.byGroup[gi]){Key k;if(wordkey(g.c,m.cand[i].lex->p,a,k))keys.insert(k);}for(auto&k:keys)votes[g.chapter][k]++;}out.key.resize(9);out.votes.resize(9);for(int ch=0;ch<9;ch++){for(auto&[k,v]:votes[ch])if(v>out.votes[ch]){out.votes[ch]=v;out.key[ch]=k;}if(out.votes[ch]>=threshold)out.support+=out.votes[ch];}return out;}
int main(int argc,char**argv){if(argc<7){cerr<<"usage: pair dictionary long.txt seed cap pairsets maxjoins\n";return 2;}for(int a=0;a<29;a++){if(a)iv[a]=inverse(a);for(int b=0;b<29;b++)mt[a][b]=a*b%29;}dictionary(argv[1]);maketrie();auto g=profile(argv[2]);int seed=stoi(argv[3]),cap=stoi(argv[4]),npair=stoi(argv[5]);long long maxjoins=stoll(argv[6]);mt19937 r(seed);bool plant=seed>=0;Chart truth=randomchart(r);vector<Key>keys(9);vector<Group>hold;int oov=0;if(plant){for(auto&k:keys)for(int&x:k)x=r()%29;for(auto&v:g){v.p=donor(v.c.size(),r);if(r()%20==0){for(int&x:v.p)x=1+r()%28;oov++;}v.c=encrypt(v.p,truth,keys[v.chapter],r()%8);}for(int ch=0;ch<9;ch++)for(int i=0;i<20;i++){Word p=donor(3+r()%6,r);hold.push_back({ch,encrypt(p,truth,keys[ch],r()%8),p});}}Model m(g);vector<vector<Active>> opt;vector<double> coverage;for(int i=0;i<(int)g.size();i++){auto all=options(m,i,0);double total=0,top=0;for(int q=0;q<(int)all.size();q++){total+=all[q].w;if(q<cap)top+=all[q].w;}coverage.push_back(total>0?top/total:0);if((int)all.size()>cap)all.resize(cap);opt.push_back(move(all));}vector<PairSet> sets;for(int i=0;i<(int)g.size();i++)for(int j=i+1;j<(int)g.size();j++)if(g[i].chapter==g[j].chapter&&g[i].c.size()>=10&&g[j].c.size()>=10&&!opt[i].empty()&&!opt[j].empty()){double n=g[i].c.size()+g[j].c.size()-8;double est=log2(double(opt[i].size())*opt[j].size())-n*1.5-2*log2(max(1e-10,coverage[i]*coverage[j]));sets.push_back({i,j,g[i].chapter,est,{}});}stable_sort(sets.begin(),sets.end(),[](auto&a,auto&b){return a.estimate<b.estimate;});vector<PairSet> chosen;vector<int> nch(9),uses(g.size());set<pair<int,int>> selected;
for(int tier=0;tier<3;tier++){for(auto&s:sets){if((int)chosen.size()>=npair)break;if(nch[s.chapter]>=4||uses[s.g]>tier||uses[s.h]>tier||selected.count({s.g,s.h}))continue;selected.insert({s.g,s.h});nch[s.chapter]++;uses[s.g]++;uses[s.h]++;chosen.push_back(move(s));}if((int)chosen.size()>=npair)break;}
sets=move(chosen);cout<<"PLANT "<<plant<<" seed="<<seed<<" oov="<<oov<<" cap="<<cap<<" sets="<<sets.size()<<endl;
 for(auto&s:sets){auto&A=opt[s.g];auto&B=opt[s.h];s.state=build(A,B);int minrank=27,maxrank=0;for(auto&h:s.state){minrank=min(minrank,h.st.rank);maxrank=max(maxrank,h.st.rank);}cout<<"set ch="<<s.chapter<<" groups="<<s.g<<","<<s.h<<" len="<<g[s.g].c.size()<<","<<g[s.h].c.size()<<" opt="<<A.size()<<","<<B.size()<<" states="<<s.state.size()<<" rank="<<minrank<<".."<<maxrank<<endl;}
 // Visit pairs with the smallest complete Cartesian product first; all hypotheses within each pair are retained.
 vector<tuple<size_t,int,int>> jobs;for(int i=0;i<(int)sets.size();i++)for(int j=i+1;j<(int)sets.size();j++)if(sets[i].chapter!=sets[j].chapter&&!sets[i].state.empty()&&!sets[j].state.empty())jobs.emplace_back(sets[i].state.size()*sets[j].state.size(),i,j);sort(jobs.begin(),jobs.end());long long joins=0,consistent=0,complete=0,charts=0,scored=0,truncated=0,gate=0;set<Chart> seen;Result best;auto start=chrono::steady_clock::now();bool found=false;int oldlimit=0;for(int limit:{32,128,512,2048,8192}){if(found||joins>=maxjoins)break;for(auto [total,i,j]:jobs){if(found||joins>=maxjoins)break;auto&A=sets[i].state;auto&B=sets[j].state;long long jb=joins,cb=consistent,fb=complete,xb=charts;int la=min((int)A.size(),limit),lb=min((int)B.size(),limit);for(int ai=0;ai<la;ai++){if(found||joins>=maxjoins)break;auto&a=A[ai];for(int bi=(ai<oldlimit?min(lb,oldlimit):0);bi<lb;bi++){if(found||joins>=maxjoins)break;auto&b=B[bi];joins++;Affine s=a.st;if(!s.join(b.st))continue;consistent++;if(s.rank<23)continue;complete++;bool all=s.charts([&](const Chart&c){charts++;if(!anchorfilter(g,c,sets[i],a,opt)||!anchorfilter(g,c,sets[j],b,opt))return true;gate++;if(!seen.insert(c).second)return true;Result q=scorechart(m,c,4);scored++;if(q.support>best.support){best=q;cout<<"BEST support="<<best.support<<" joins="<<joins<<" matches="<<(plant?match(c,truth):0)<<endl;}if(q.support>=120){found=true;best=q;return false;}return true;});truncated+=!all;}}
 if(charts>xb||found)cout<<"join tier="<<limit<<" "<<i<<","<<j<<" done="<<joins-jb<<" consistent="<<consistent-cb<<" dimle4="<<complete-fb<<" charts="<<charts-xb<<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<endl;}
 cout<<"TIER "<<limit<<" joins="<<joins<<" consistent="<<consistent<<" complete="<<complete<<" charts="<<charts<<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<endl;oldlimit=limit;}
 long long triple=0,tripleConsistent=0,tripleRank=0;long long tripleLimit=5000000;vector<vector<int>> third(sets.size());for(int i=0;i<(int)sets.size();i++){auto&s=sets[i];for(int k=0;k<(int)g.size();k++)if(g[k].chapter==s.chapter&&k!=s.g&&k!=s.h&&g[k].c.size()>=9&&!opt[k].empty())third[i].push_back(k);stable_sort(third[i].begin(),third[i].end(),[&](int a,int b){auto val=[&](int j){return 1.5*g[j].c.size()-log2(opt[j].size())+2*log2(max(1e-10,coverage[j]));};return val(a)>val(b);});if(third[i].size()>8)third[i].resize(8);}
 int old=0;for(int limit:{16,64,256,1024,4096}){if(found||triple>=tripleLimit)break;for(int i=0;i<(int)sets.size();i++){auto&s=sets[i];if(found||triple>=tripleLimit)break;for(int ai=old;ai<min(limit,(int)s.state.size());ai++){auto&a=s.state[ai];if(found||triple>=tripleLimit)break;for(int k:third[i]){if(found||triple>=tripleLimit)break;for(auto&op:opt[k]){if(found||triple>=tripleLimit)break;for(int ph=0;ph<8;ph++){if(found||triple>=tripleLimit)break;triple++;Affine q=a.st;if(!addsecond(q,opt[s.g][a.a],op,ph))continue;tripleConsistent++;if(q.rank<23)continue;tripleRank++;bool all=q.charts([&](const Chart&c){charts++;if(!anchorfilter(g,c,s,a,opt))return true;gate++;if(!seen.insert(c).second)return true;Result rr=scorechart(m,c,4);scored++;if(rr.support>best.support){best=rr;cout<<"BEST_TRIPLE support="<<best.support<<" joins="<<triple<<" matches="<<(plant?match(c,truth):0)<<endl;}if(rr.support>=120){found=true;best=rr;return false;}return true;});truncated+=!all;}}}}}cout<<"TRIPLE_TIER "<<limit<<" extensions="<<triple<<" consistent="<<tripleConsistent<<" rank="<<tripleRank<<" charts="<<charts<<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<endl;old=limit;}
 cout<<"FINAL triple="<<triple<<" tripleConsistent="<<tripleConsistent<<" tripleRank="<<tripleRank<<" joins="<<joins<<" consistent="<<consistent<<" dimle4="<<complete<<" charts="<<charts<<" gate="<<gate<<" truncated="<<truncated<<" scored="<<scored<<" support="<<best.support<<" chart_match="<<(plant?match(best.chart,truth):0)<<" chart=";for(int x:best.chart)cout<<x<<",";cout<<endl;if(best.support)keytest(m,best.chart,keys,hold,plant);return 0;}
